import {esc} from './paper-render.js?v=20261118-wordlinks';
import {NOTE_SOURCES,noteSource} from './notebook-core.js?v=20261118-wordlinks';
import {shapes} from './paper-shapes.js';
import {PEN_WIDTH_PRESETS} from './paper-core.js?v=pen-width-20261119';
export const colors=['#172033','#3155d9','#15966d','#dc4343','#8756c6','#ef9e39'];
const icons={select:'↖',pen:'✎',highlight:'▰',eraser:'◇',text:'T',shape:'△',image:'▧',hand:'✋',undo:'↶',redo:'↷'};
export function paperPage(space,n){return `<section class="paper-app" aria-label="สมุดกระดาษ"><header class="paper-header"><a class="paper-back" href="#notes" aria-label="กลับสมุดจด">‹</a><div class="paper-heading"><span class="paper-eyebrow">MY NOTEBOOK <span> / ${esc(n.course||'ทั่วไป')}</span></span><input id="paper-title" aria-label="ชื่อโน้ต" maxlength="160" value="${esc(n.title)}"><span class="paper-cloud" data-sync-status role="status">${esc(space.info().status)}</span></div><button class="paper-save" data-paper="save">บันทึกงาน</button><details class="paper-menu"><summary aria-label="ตัวเลือกโน้ต">•••</summary><div><button data-action="nb-pin" data-id="${n.id}">${n.pinned?'เลิกปักหมุด':'ปักหมุดโน้ต'}</button><button data-action="nb-archive" data-id="${n.id}">${n.archived?'นำกลับมาใช้':'เก็บเข้าคลัง'}</button><button data-action="nb-print">พิมพ์หน้านี้</button><button data-action="nb-export">สำรองโน้ตพร้อมรูป</button><button data-paper="legacy">ดูต้นฉบับเดิม</button><button data-action="nb-delete" data-id="${n.id}" class="paper-danger">ลบโน้ต</button></div></details></header>
 <div class="paper-toolbar"><div class="paper-toolset" role="group" aria-label="เครื่องมือจด">${Object.entries(icons).map(([key,icon])=>`<button type="button" data-paper="${key}" aria-label="${({select:'เลือกและย้าย',pen:'ปากกา',highlight:'ไฮไลต์',eraser:'ยางลบ',text:'ข้อความ',shape:'รูปทรง',image:'แทรกรูป',hand:'เลื่อนกระดาษ',undo:'ย้อนกลับ',redo:'ทำซ้ำ'})[key]}" title="${key}"><span>${icon}</span><small>${({select:'เลือก',pen:'ปากกา',highlight:'ไฮไลต์',eraser:'ลบเส้น',text:'ข้อความ',shape:'รูปทรง',image:'รูป',hand:'เลื่อน',undo:'ย้อนกลับ',redo:'ทำซ้ำ'})[key]}</small></button>`).join('')}</div><div class="paper-tool-options"><button data-paper="word-link" title="เลือกข้อความแล้วเชื่อมกับเว็บหรือไฟล์ (Ctrl/Cmd + K)">เชื่อมคำกับเว็บ/ไฟล์</button><button data-paper="multi" aria-pressed="false" title="Shift + คลิก เพื่อเพิ่มหรือเอาออกจากกลุ่ม">เลือกหลายชิ้น</button><label id="paper-shape-options" hidden>รูปทรง <select id="paper-shape">${Object.entries(shapes).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><div class="paper-colors" aria-label="สี">${colors.map(c=>`<button data-paper-color="${c}" style="--ink:${c}" aria-label="สี ${c}"></button>`).join('')}</div><div class="paper-pen-sizes" role="group" aria-label="เลือกขนาดเส้นปากกา"><button type="button" class="paper-size-toggle" data-paper-size-toggle="true" aria-expanded="false" aria-controls="paper-size-controls" title="เลือกขนาดเส้นปากกา">✎ เส้น <span id="paper-width-mobile-value">5</span> ▾</button><div class="paper-size-controls" id="paper-size-controls"><span class="paper-size-label">ความหนาปากกา (1 = บาง · 12 = หนา) · เลือกจุดหรือเลื่อนแถบได้</span><div class="paper-size-presets">${PEN_WIDTH_PRESETS.map(v=>`<button type="button" class="paper-size-preset" data-paper-width="${v}" aria-label="เส้นขนาด ${v}" title="เส้นขนาด ${v}" aria-pressed="${v===5}"><span style="width:${Math.max(3,v+2)}px;height:${Math.max(3,v+2)}px"></span></button>`).join('')}</div><label class="paper-size-slider" for="paper-width"><span class="sr-only">ปรับขนาดเส้นละเอียด</span><input id="paper-width" aria-label="ปรับความหนาของเส้นปากกา" type="range" min="1" max="12" step="1" value="5"></label><output id="paper-width-value" for="paper-width" aria-live="polite">5</output><span class="paper-pen-preview" title="ตัวอย่างความหนาของเส้น"><i id="paper-pen-preview" style="width:5px;height:5px"></i></span></div></div><label class="paper-finger"><input id="paper-finger" type="checkbox">นิ้วเขียน</label><button data-paper="pages" class="paper-pages-toggle">▤ หน้า</button></div></div>
 <div class="paper-workspace"><aside class="paper-pages"><div class="paper-pages-heading"><b>หน้ากระดาษ</b><button data-paper="add-page" aria-label="เพิ่มหน้า">＋</button></div><div id="paper-page-list"></div><button data-paper="add-page" class="paper-add-page">＋ เพิ่มหน้า</button></aside><div class="paper-center"><div class="paper-context"><label>กระดาษ <select id="paper-template"><option value="plain">ว่าง</option><option value="ruled">เส้นบรรทัด</option><option value="grid">ตาราง</option><option value="dots">จุด</option></select></label><div class="paper-context-actions"><button data-paper="duplicate-page" title="ทำสำเนาหน้า">ทำสำเนา</button><button data-paper="delete-page">ลบหน้า</button><button data-paper="files" title="แนบ PDF, Word หรือ PowerPoint">แนบไฟล์</button><button data-paper="info">รายละเอียด</button></div></div><div id="paper-viewport" class="paper-viewport"><div id="paper-wrap" class="paper-wrap"><div id="paper-sheet" class="paper-sheet"><svg id="paper-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1273" role="img" aria-label="หน้ากระดาษสำหรับเขียน พิมพ์ และวางรูป"></svg><textarea id="paper-text-input" hidden aria-label="แก้ข้อความบนกระดาษ" spellcheck="false"></textarea></div></div></div><div class="paper-bottom"><span id="paper-page-label">กำลังเปิดสมุด…</span><span id="paper-hint" role="status">แตะบนกระดาษเพื่อพิมพ์ · แตะรูปเพื่อย้ายหรือปรับขนาด</span><div><button data-paper="zoom-out" aria-label="ย่อกระดาษ">−</button><button data-paper="fit" id="paper-zoom">พอดีหน้า</button><button data-paper="zoom-in" aria-label="ขยายกระดาษ">＋</button></div></div></div></div>
 <div id="paper-selection-tools" class="paper-selection-tools" hidden><span>เลือกแล้ว <b id="paper-selected-count"></b></span><button data-paper="edit-text">แก้ข้อความ</button><label>ขนาดตัวอักษร <select id="paper-font-size">${[16,20,24,32,40,56].map(v=>`<option>${v}</option>`).join('')}</select></label><button data-paper="bold">ตัวหนา</button><button data-paper="image-link" hidden>ใส่ลิงก์</button><a id="paper-open-link" hidden target="_blank" rel="noopener noreferrer">เปิดลิงก์ ↗</a><button data-paper="crop" hidden>ครอปรูป</button><button data-paper="duplicate">ทำสำเนา</button><button data-paper="delete-object" class="paper-danger">ลบที่เลือก</button></div>
 <aside id="paper-info" class="paper-info" hidden><div><h2>รายละเอียดโน้ต</h2><button data-paper="info">ปิด</button></div><label>วิชา<input id="paper-course" value="${esc(n.course)}" placeholder="POL1101"></label><label>ประเภทโน้ต<select id="paper-source">${Object.entries(NOTE_SOURCES).map(([k,v])=>`<option value="${k}" ${k===noteSource(n)?"selected":""}>${v}</option>`).join("")}</select></label><label>แท็ก<input id="paper-tags" maxlength="250" value="${esc(n.tags)}"></label><label>คำถามทบทวน<textarea id="paper-question" maxlength="4000">${esc(n.question)}</textarea></label><label>คำตอบ<textarea id="paper-answer" maxlength="10000">${esc(n.answer)}</textarea></label><p>หน้ากระดาษเดียวกันทุกเครื่อง ไม่ต้องล็อกอิน</p><a href="#account">ข้อมูลและการซิงก์ →</a></aside><dialog id="paper-link-dialog" class="paper-sheet-dialog"><form method="dialog"><h2>ลิงก์ของรูปภาพ</h2><label>เว็บไซต์<input name="url" type="url" maxlength="2048" placeholder="https://…" autofocus></label><p role="status"></p><div class="paper-dialog-actions"><button value="save">บันทึกลิงก์</button><button value="remove" formnovalidate>ลบลิงก์</button><button value="cancel" formnovalidate>ยกเลิก</button></div></form></dialog><dialog id="paper-files" class="paper-sheet-dialog"><header><h2>ไฟล์แนบ</h2><form method="dialog"><button>ปิด</button></form></header><ul id="paper-file-list"></ul><label>แนบ PDF, Word หรือ PowerPoint (ไม่เกิน 2 MB ต่อไฟล์)<input type="file" id="paper-doc-file" accept=".pdf,.doc,.docx,.ppt,.pptx"></label><p id="paper-file-status" role="status"></p></dialog><input id="paper-image-file" hidden type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></section>`;}
